// Package localtls supplies local trust to child processes without changing
// machine trust, the parent process environment, or project configuration.
package localtls

import (
	"bytes"
	"crypto/tls"
	"crypto/x509"
	"encoding/pem"
	"errors"
	"fmt"
	"io"
	"net/url"
	"os"
	"path/filepath"
	"strings"
)

// Project identifies an HTTPS-enabled local checkout and its existing leaf
// certificate. No certificate is generated by Environment.
type Project struct {
	Path, Hostname, CertPath, KeyPath string
}

// PublicCertificates parses a PEM bundle, rejects non-certificate material,
// and returns only certificate PEM blocks. Comments in Mozilla bundles are
// accepted; private keys are never copied into a trust bundle or environment.
func PublicCertificates(data []byte) ([]byte, error) {
	if bytes.Contains(data, []byte("PRIVATE KEY")) {
		return nil, errors.New("public certificate input contains private-key material")
	}
	var out []byte
	for len(data) > 0 {
		block, rest := pem.Decode(data)
		if block == nil {
			break
		}
		if block.Type != "CERTIFICATE" {
			return nil, errors.New("public certificate input contains a non-certificate PEM block")
		}
		if _, err := x509.ParseCertificate(block.Bytes); err != nil {
			return nil, errors.New("public certificate input contains an invalid certificate")
		}
		out = append(out, pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: block.Bytes})...)
		data = rest
	}
	if len(out) == 0 {
		return nil, errors.New("public certificate input has no certificates")
	}
	return out, nil
}

// ReadCA returns validated public CA certificates only, with bounded reads.
func ReadCA(path string) ([]byte, error) {
	data, err := readBounded(path, 1024*1024)
	if err != nil {
		return nil, err
	}
	public, err := PublicCertificates(data)
	if err != nil {
		return nil, err
	}
	for rest := public; len(rest) > 0; {
		block, tail := pem.Decode(rest)
		cert, _ := x509.ParseCertificate(block.Bytes)
		if !cert.IsCA || cert.KeyUsage&x509.KeyUsageCertSign == 0 {
			return nil, errors.New("local trust certificate is not a certificate authority")
		}
		rest = tail
	}
	return public, nil
}

// Environment adds the public local CA for Node/npm and, when supported by
// the installed Laravel Vite plugin, existing HTTPS leaf paths. Explicit user
// environment (even an empty value or differently cased key) always wins.
// Project .env TLS choices also win. The returned slice never aliases env.
func Environment(env []string, caCertPath string, project *Project) ([]string, error) {
	out := append([]string(nil), env...)
	if caCertPath == "" {
		return out, nil
	}
	publicCA, err := ReadCA(caCertPath)
	if err != nil {
		if os.IsNotExist(err) {
			return out, nil
		}
		return nil, fmt.Errorf("read local public CA: %w", err)
	}
	if _, exists := envValue(out, "NODE_EXTRA_CA_CERTS"); !exists {
		out = append(out, "NODE_EXTRA_CA_CERTS="+caCertPath)
	}
	if project == nil || project.Hostname == "" {
		return out, nil
	}
	for _, key := range []string{"VITE_DEV_SERVER_KEY", "VITE_DEV_SERVER_CERT"} {
		if _, exists := envValue(out, key); exists {
			return out, nil
		}
	}
	if !supportsLaravelVite(project.Path) {
		return out, nil
	}
	values, ok := projectEnvironment(project.Path)
	if !ok {
		return out, nil
	}
	for _, key := range []string{"VITE_DEV_SERVER_KEY", "VITE_DEV_SERVER_CERT"} {
		if _, exists := values[key]; exists {
			return out, nil
		}
	}
	appURL, supplied := envValue(out, "APP_URL")
	if !supplied {
		appURL, supplied = values["APP_URL"]
	}
	if supplied {
		u, err := url.Parse(appURL)
		// Laravel Vite derives its HMR/bind host from APP_URL; do not inject
		// a certificate for another hostname or silently change that setting.
		if err != nil || !strings.EqualFold(u.Hostname(), project.Hostname) || u.Port() != "" {
			return out, nil
		}
	}
	pair, err := tls.LoadX509KeyPair(project.CertPath, project.KeyPath)
	if err != nil {
		return out, nil
	}
	leaf, err := x509.ParseCertificate(pair.Certificate[0])
	if err != nil || leaf.VerifyHostname(project.Hostname) != nil {
		return out, nil
	}
	roots := x509.NewCertPool()
	roots.AppendCertsFromPEM(publicCA)
	intermediates := x509.NewCertPool()
	for _, der := range pair.Certificate[1:] {
		cert, err := x509.ParseCertificate(der)
		if err != nil {
			return out, nil
		}
		intermediates.AddCert(cert)
	}
	if _, err := leaf.Verify(x509.VerifyOptions{DNSName: project.Hostname, Roots: roots, Intermediates: intermediates}); err != nil {
		return out, nil
	}
	if !supplied {
		out = append(out, "APP_URL=https://"+project.Hostname)
	}
	return append(out, "VITE_DEV_SERVER_KEY="+project.KeyPath, "VITE_DEV_SERVER_CERT="+project.CertPath), nil
}

func envValue(env []string, key string) (string, bool) {
	for i := len(env) - 1; i >= 0; i-- {
		if at := strings.IndexByte(env[i], '='); at > 0 && strings.EqualFold(env[i][:at], key) {
			return env[i][at+1:], true
		}
	}
	return "", false
}

func supportsLaravelVite(projectPath string) bool {
	if st, err := os.Stat(filepath.Join(projectPath, "artisan")); err != nil || !st.Mode().IsRegular() {
		return false
	}
	// Inspect the installed plugin, not an assumed version: unsupported or
	// absent installations keep their existing HTTP/configured behavior.
	for _, entry := range []string{"dist/index.js", "dist/index.mjs", "src/index.ts"} {
		data, err := readBounded(filepath.Join(projectPath, "node_modules/laravel-vite-plugin", filepath.FromSlash(entry)), 2*1024*1024)
		if err == nil && bytes.Contains(data, []byte("VITE_DEV_SERVER_KEY")) && bytes.Contains(data, []byte("VITE_DEV_SERVER_CERT")) {
			return true
		}
	}
	return false
}

// Read only the relevant names; never return or log unrelated .env secrets.
// An ambiguous/unreadable file conservatively disables Vite auto-configuration.
func projectEnvironment(dir string) (map[string]string, bool) {
	values := map[string]string{}
	files := []string{".env", ".env.local", ".env.development", ".env.development.local"}
	known := map[string]bool{}
	for _, file := range files {
		known[file] = true
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, false
	}
	var modeFiles []string
	for _, entry := range entries {
		name := entry.Name()
		if strings.HasPrefix(name, ".env.") && name != ".env.example" && !known[name] {
			modeFiles = append(modeFiles, name)
		}
	}
	if len(modeFiles) > 64 {
		return nil, false
	}
	files = append(files, modeFiles...)
	for _, file := range files {
		data, err := readBounded(filepath.Join(dir, file), 256*1024)
		if os.IsNotExist(err) {
			continue
		}
		if err != nil {
			return nil, false
		}
		for _, line := range strings.Split(string(data), "\n") {
			line = strings.TrimPrefix(strings.TrimSpace(line), "\ufeff")
			line = strings.TrimSpace(strings.TrimPrefix(line, "export "))
			key, value, found := strings.Cut(line, "=")
			key = strings.ToUpper(strings.TrimSpace(key))
			if !found || (key != "APP_URL" && key != "VITE_DEV_SERVER_KEY" && key != "VITE_DEV_SERVER_CERT") {
				continue
			}
			value = strings.TrimSpace(value)
			if len(value) > 0 && (value[0] == '\'' || value[0] == '"') {
				quote := value[0]
				end := strings.IndexByte(value[1:], quote)
				if end < 0 {
					return nil, false
				}
				value = value[1 : end+1]
			} else if hash := strings.IndexByte(value, '#'); hash >= 0 {
				value = strings.TrimSpace(value[:hash])
			}
			if !known[file] && key == "APP_URL" {
				// A shell may later start Vite with --mode <custom>. A parent
				// APP_URL override would win over that mode's explicit value.
				if current, exists := values[key]; !exists || current != value {
					return nil, false
				}
				continue
			}
			values[key] = value
		}
	}
	return values, true
}

func readBounded(path string, maxBytes int64) ([]byte, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	st, err := f.Stat()
	if err != nil {
		return nil, err
	}
	if !st.Mode().IsRegular() || st.Size() > maxBytes {
		return nil, errors.New("certificate or configuration file exceeds the supported size or is not a regular file")
	}
	data, err := io.ReadAll(io.LimitReader(f, maxBytes+1))
	if err == nil && int64(len(data)) > maxBytes {
		return nil, errors.New("certificate or configuration file exceeds the supported size")
	}
	return data, err
}
